export function ComponentLibrary({
  libraryName = "{{libraryName}}",
  activeComponent = "{{activeComponent}}",
  accent = "{{accent}}",
  showLabels = {{showLabels}},
}) {
  const items = [
    { key: "button", swatch: "Btn", label: "Button" },
    { key: "card", swatch: "", label: "Card" },
    { key: "badge", swatch: "\u2022", label: "Badge" },
    { key: "input", swatch: "|", label: "Input" },
  ];
  return (
    <div role="img" aria-label={`${libraryName} component library, ${activeComponent} selected`}
      style={{ font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 12px", fontWeight: 700 }}>{libraryName}</p>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 10, textAlign: "center" }}>
        {items.map((it) => (
          <div key={it.key} style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>
            <span style={{ display: "grid", placeItems: "center", width: "100%", height: 44, borderRadius: 8, fontSize: 12, boxSizing: "border-box",
              border: `2px solid ${it.key === activeComponent ? accent : "transparent"}`,
              background: it.key === activeComponent ? `color-mix(in srgb, ${accent} 30%, #FAF7F2)` : "#24143010" }}>{it.swatch}</span>
            {showLabels && <small style={{ fontSize: 10, color: "#24143099" }}>{it.label}</small>}
          </div>
        ))}
      </div>
    </div>
  );
}
